def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); candidates=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 or (r,c) in seen: continue
            color=grid[r][c]; comp={(r,c)}; seen.add((r,c)); stack=[(r,c)]
            while stack:
                x,y=stack.pop()
                for dx in (-1,0,1):
                    for dy in (-1,0,1):
                        a,b=x+dx,y+dy
                        if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen:
                            seen.add((a,b));comp.add((a,b));stack.append((a,b))
            a=min(x for x,y in comp);b=max(x for x,y in comp);l=min(y for x,y in comp);u=max(y for x,y in comp)
            outside={(a-1,l-1)}; stack=list(outside)
            while stack:
                x,y=stack.pop()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    p,q=x+dx,y+dy
                    if a-1<=p<=b+1 and l-1<=q<=u+1 and (p,q) not in comp and (p,q) not in outside:
                        outside.add((p,q));stack.append((p,q))
            if all((x,y) in comp or (x,y) in outside for x in range(a,b+1) for y in range(l,u+1)):
                candidates.append((b-a+1,u-l+1))
    hh,ww=candidates[0] if candidates else (1,1)
    return [[0]*ww for _ in range(hh)]

